import { useParams, useNavigate } from 'react-router';
import {
  Card, Button, Table, Typography, Space, Alert, Tag, Descriptions, App as AntApp,
} from 'antd';
import { CheckOutlined, ArrowLeftOutlined } from '@ant-design/icons';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api, getErrorMessage } from '../../lib/api';
import { formatETB } from '../../lib/formatters';
import type { ComputeAllocationResponse } from '@phison/types';
import { PaymentsSubNav } from '../../components/shared/SubNav';
import DatePicker from 'antd/es/date-picker/index';
import { useState } from 'react';
import dayjs from 'dayjs';

const { Title, Text } = Typography;

export default function AllocationPage() {
  const { paymentId } = useParams<{ paymentId: string }>();
  const navigate = useNavigate();
  const { message } = AntApp.useApp();
  const qc = useQueryClient();
  const [dueDate, setDueDate] = useState<dayjs.Dayjs | null>(null);

  const { data, isLoading, error } = useQuery({
    queryKey: ['allocation-preview', paymentId],
    queryFn: () =>
      api.post<ComputeAllocationResponse>(`/payments/allocations/compute/${paymentId}`).then(r => r.data),
    enabled: !!paymentId,
  });

  const confirmMutation = useMutation({
    mutationFn: () =>
      api.post('/payments/allocations/confirm', {
        allocationId: data?.allocationId,
        dueDate: dueDate?.toISOString(),
      }),
    onSuccess: () => {
      message.success('Allocation confirmed and charges created');
      qc.invalidateQueries({ queryKey: ['provider-payments'] });
      navigate('/admin/payments/charges');
    },
    onError: (e) => message.error(getErrorMessage(e)),
  });

  if (error) {
    return <Alert type="error" message={getErrorMessage(error)} showIcon />;
  }

  const columns = [
    { title: 'Unit', dataIndex: 'unitIdentifier', key: 'unit' },
    { title: 'Payer', dataIndex: 'payerName', key: 'payer', render: (n: string | null) => n ?? <Text type="danger">Unlinked</Text> },
    { title: 'Role', dataIndex: 'payerRole', key: 'role', render: (r: string | null) => r ? <Tag>{r}</Tag> : '—' },
    { title: 'Share', dataIndex: 'shareAmount', key: 'share', render: (a: number) => formatETB(a) },
  ];

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      <PaymentsSubNav />
      <Space>
        <Button icon={<ArrowLeftOutlined />} onClick={() => navigate(-1)}>Back</Button>
        <Title level={4} style={{ margin: 0 }}>Allocation Preview</Title>
      </Space>

      {data && (
        <>
          {!data.valid && (
            <Alert
              type="error"
              showIcon
              message={`Allocation totals do not balance. Difference: ${formatETB(data.difference)}`}
            />
          )}
          {data.unlinkedUnits.length > 0 && (
            <Alert
              type="warning"
              showIcon
              message={`Units with no active residents (skipped): ${data.unlinkedUnits.join(', ')}`}
            />
          )}

          <Card>
            <Descriptions column={3}>
              <Descriptions.Item label="Provider Payment">{formatETB(data.providerPaymentAmount)}</Descriptions.Item>
              <Descriptions.Item label="Computed Total">{formatETB(data.totalComputed)}</Descriptions.Item>
              <Descriptions.Item label="Difference">
                <Text type={data.difference === 0 ? 'success' : 'danger'}>{formatETB(data.difference)}</Text>
              </Descriptions.Item>
            </Descriptions>
          </Card>

          <Table
            dataSource={data.lines}
            columns={columns}
            rowKey={r => `${r.unitId}-${r.payerId}`}
            loading={isLoading}
            pagination={false}
          />

          <Card title="Set Due Date">
            <Space>
              <DatePicker
                value={dueDate}
                onChange={setDueDate}
                disabledDate={d => d.isBefore(dayjs(), 'day')}
                placeholder="Select due date"
              />
              <Button
                type="primary"
                icon={<CheckOutlined />}
                disabled={!data.valid || !dueDate}
                loading={confirmMutation.isPending}
                onClick={() => confirmMutation.mutate()}
              >
                Confirm Allocation
              </Button>
            </Space>
          </Card>
        </>
      )}
    </Space>
  );
}
